-- AF-02 Feedback Board. Direct table access is denied; consumer access uses
-- these scoped RPCs so unpublished and anonymous content remains private.
create table if not exists public.feedback_posts (id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,category text not null check(category in ('review','suggestion','recommendation','bug','praise')),title text not null check(char_length(trim(title)) between 3 and 140),body text not null check(char_length(trim(body)) between 3 and 5000),rating smallint check(rating between 1 and 5),module text,is_anonymous boolean not null default false,app_version text,platform text,source text not null default 'board',status text not null default 'open' check(status in ('open','under_review','planned','in_progress','shipped','closed')),status_note text,visibility text not null default 'published' check(visibility in ('published','pending','hidden')),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.feedback_post_votes(post_id uuid not null references public.feedback_posts(id) on delete cascade,user_id uuid not null references auth.users(id) on delete cascade,created_at timestamptz not null default now(),primary key(post_id,user_id));
create table if not exists public.feedback_post_watches(post_id uuid not null references public.feedback_posts(id) on delete cascade,user_id uuid not null references auth.users(id) on delete cascade,created_at timestamptz not null default now(),primary key(post_id,user_id));
create table if not exists public.feedback_post_flags(id bigint generated by default as identity primary key,post_id uuid not null references public.feedback_posts(id) on delete cascade,user_id uuid not null references auth.users(id) on delete cascade,reason text,created_at timestamptz not null default now(),unique(post_id,user_id));
create table if not exists public.feedback_post_replies(id uuid primary key default gen_random_uuid(),post_id uuid not null references public.feedback_posts(id) on delete cascade,author_user_id uuid not null references auth.users(id) on delete cascade,body text not null check(char_length(trim(body)) between 1 and 3000),is_staff boolean not null default false,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create index if not exists feedback_posts_visibility_created_idx on public.feedback_posts(visibility,created_at desc); create index if not exists feedback_posts_user_created_idx on public.feedback_posts(user_id,created_at desc); create index if not exists feedback_replies_post_created_idx on public.feedback_post_replies(post_id,created_at);
alter table public.feedback_posts enable row level security;alter table public.feedback_post_votes enable row level security;alter table public.feedback_post_watches enable row level security;alter table public.feedback_post_flags enable row level security;alter table public.feedback_post_replies enable row level security;revoke all on public.feedback_posts,public.feedback_post_votes,public.feedback_post_watches,public.feedback_post_flags,public.feedback_post_replies from anon,authenticated;
create or replace function public.get_feedback_board(p_category text default null,p_status text default null,p_module text default null,p_sort text default 'top',p_mine boolean default false,p_limit int default 30,p_offset int default 0) returns jsonb language plpgsql stable security definer set search_path to 'public' as $$ declare v_me uuid:=auth.uid();v_admin boolean:=false;begin if v_me is null then raise exception 'Not authenticated' using errcode='42501';end if;if p_category is not null and p_category not in ('review','suggestion','recommendation','bug','praise') then raise exception 'Invalid category' using errcode='22023';end if;if p_status is not null and p_status not in ('open','under_review','planned','in_progress','shipped','closed') then raise exception 'Invalid status' using errcode='22023';end if;if p_sort not in ('top','new','status') then raise exception 'Invalid sort' using errcode='22023';end if;p_limit:=greatest(1,least(coalesce(p_limit,30),100));p_offset:=greatest(0,coalesce(p_offset,0));begin select public.is_app_admin() into v_admin;exception when undefined_function then v_admin:=false;end;return jsonb_build_object('posts',coalesce((select jsonb_agg(jsonb_build_object('id',x.id,'category',x.category,'user_id',case when x.is_anonymous and x.user_id<>v_me then null else x.user_id end,'title',x.title,'body_preview',left(x.body,280),'rating',x.rating,'module',x.module,'status',x.status,'status_note',x.status_note,'vote_count',x.vote_count,'flag_count',x.flag_count,'created_at',x.created_at,'is_mine',x.user_id=v_me,'voted',x.voted,'reply_count',x.reply_count)) from (select p.*,count(distinct v.user_id) as vote_count,count(distinct f.user_id) as flag_count,count(distinct r.id) as reply_count,exists(select 1 from public.feedback_post_votes myv where myv.post_id=p.id and myv.user_id=v_me) as voted from public.feedback_posts p left join public.feedback_post_votes v on v.post_id=p.id left join public.feedback_post_flags f on f.post_id=p.id left join public.feedback_post_replies r on r.post_id=p.id where(case when p_mine then p.user_id=v_me else p.visibility='published' or p.user_id=v_me or v_admin end)and(p_category is null or p.category=p_category)and(p_status is null or p.status=p_status)and(p_module is null or p.module=p_module) group by p.id order by case when p_sort='top' then count(distinct v.user_id) end desc,case when p_sort='status' then p.status end asc,p.created_at desc limit p_limit offset p_offset)x),'[]'::jsonb));end $$;
create or replace function public.get_feedback_post(p_post_id uuid) returns jsonb language plpgsql stable security definer set search_path to 'public' as $$ declare v_me uuid:=auth.uid();v_post public.feedback_posts%rowtype;v_admin boolean:=false;begin if v_me is null then raise exception 'Not authenticated' using errcode='42501';end if;select * into v_post from public.feedback_posts where id=p_post_id;if not found then raise exception 'Feedback post not found' using errcode='P0002';end if;begin select public.is_app_admin() into v_admin;exception when undefined_function then v_admin:=false;end;if v_post.visibility<>'published' and v_post.user_id<>v_me and not v_admin then raise exception 'Not authorized' using errcode='42501';end if;return jsonb_build_object('post',jsonb_build_object('id',v_post.id,'category',v_post.category,'user_id',case when v_post.is_anonymous and v_post.user_id<>v_me then null else v_post.user_id end,'title',v_post.title,'body',v_post.body,'rating',v_post.rating,'module',v_post.module,'status',v_post.status,'status_note',v_post.status_note,'vote_count',(select count(*) from public.feedback_post_votes where post_id=v_post.id),'created_at',v_post.created_at,'is_mine',v_post.user_id=v_me,'voted',exists(select 1 from public.feedback_post_votes where post_id=v_post.id and user_id=v_me),'watching',exists(select 1 from public.feedback_post_watches where post_id=v_post.id and user_id=v_me)),'replies',coalesce((select jsonb_agg(jsonb_build_object('id',r.id,'author_user_id',case when v_post.is_anonymous and not r.is_staff then null else r.author_user_id end,'is_staff',r.is_staff,'body',r.body,'created_at',r.created_at) order by r.created_at) from public.feedback_post_replies r where r.post_id=v_post.id),'[]'::jsonb));end $$;
create or replace function public.submit_feedback_post(p_category text,p_title text,p_body text,p_rating smallint default null,p_module text default null,p_is_anonymous boolean default false,p_app_version text default null,p_platform text default null,p_source text default 'board') returns jsonb language plpgsql security definer set search_path to 'public' as $$ declare v_me uuid:=auth.uid();v_id uuid;begin if v_me is null then raise exception 'Not authenticated' using errcode='42501';end if;if p_category not in ('review','suggestion','recommendation','bug','praise') or char_length(trim(coalesce(p_title,''))) not between 3 and 140 or char_length(trim(coalesce(p_body,''))) not between 3 and 5000 or(p_rating is not null and p_rating not between 1 and 5)then raise exception 'Invalid feedback' using errcode='22023';end if;insert into public.feedback_posts(user_id,category,title,body,rating,module,is_anonymous,app_version,platform,source)values(v_me,p_category,trim(p_title),trim(p_body),p_rating,nullif(trim(p_module),''),coalesce(p_is_anonymous,false),nullif(trim(p_app_version),''),nullif(trim(p_platform),''),coalesce(nullif(trim(p_source),''),'board'))returning id into v_id;return jsonb_build_object('ok',true,'id',v_id,'visibility','published');end $$;
create or replace function public.vote_feedback_post(p_post_id uuid) returns jsonb language plpgsql security definer set search_path to 'public' as $$ declare v_me uuid:=auth.uid();v_voted boolean;begin if v_me is null then raise exception 'Not authenticated' using errcode='42501';end if;if not exists(select 1 from public.feedback_posts where id=p_post_id and visibility='published')then raise exception 'Feedback post not found' using errcode='P0002';end if;delete from public.feedback_post_votes where post_id=p_post_id and user_id=v_me returning true into v_voted;if v_voted then v_voted:=false;else insert into public.feedback_post_votes(post_id,user_id)values(p_post_id,v_me);v_voted:=true;end if;return jsonb_build_object('ok',true,'voted',v_voted,'vote_count',(select count(*) from public.feedback_post_votes where post_id=p_post_id));end $$;
create or replace function public.watch_feedback_post(p_post_id uuid) returns jsonb language plpgsql security definer set search_path to 'public' as $$ declare v_me uuid:=auth.uid();v_watching boolean;begin if v_me is null then raise exception 'Not authenticated' using errcode='42501';end if;if not exists(select 1 from public.feedback_posts where id=p_post_id and(visibility='published'or user_id=v_me))then raise exception 'Feedback post not found' using errcode='P0002';end if;delete from public.feedback_post_watches where post_id=p_post_id and user_id=v_me returning true into v_watching;if v_watching then v_watching:=false;else insert into public.feedback_post_watches(post_id,user_id)values(p_post_id,v_me);v_watching:=true;end if;return jsonb_build_object('ok',true,'watching',v_watching);end $$;
create or replace function public.flag_feedback_post(p_post_id uuid,p_reason text default null) returns jsonb language plpgsql security definer set search_path to 'public' as $$ declare v_me uuid:=auth.uid();v_count int;begin if v_me is null then raise exception 'Not authenticated' using errcode='42501';end if;if not exists(select 1 from public.feedback_posts where id=p_post_id and visibility='published')then raise exception 'Feedback post not found' using errcode='P0002';end if;insert into public.feedback_post_flags(post_id,user_id,reason)values(p_post_id,v_me,nullif(trim(p_reason),''))on conflict(post_id,user_id)do nothing;select count(*)into v_count from public.feedback_post_flags where post_id=p_post_id;return jsonb_build_object('ok',true,'flag_count',v_count);end $$;
create or replace function public.reply_feedback_post(p_post_id uuid,p_body text) returns jsonb language plpgsql security definer set search_path to 'public' as $$ declare v_me uuid:=auth.uid();v_id uuid;v_staff boolean:=false;begin if v_me is null then raise exception 'Not authenticated' using errcode='42501';end if;if char_length(trim(coalesce(p_body,''))) not between 1 and 3000 or not exists(select 1 from public.feedback_posts where id=p_post_id and(visibility='published'or user_id=v_me))then raise exception 'Invalid reply or feedback post' using errcode='22023';end if;begin select public.is_app_admin()into v_staff;exception when undefined_function then v_staff:=false;end;insert into public.feedback_post_replies(post_id,author_user_id,body,is_staff)values(p_post_id,v_me,trim(p_body),coalesce(v_staff,false))returning id into v_id;return jsonb_build_object('ok',true,'id',v_id);end $$;
revoke all on function public.get_feedback_board(text,text,text,text,boolean,int,int),public.get_feedback_post(uuid),public.submit_feedback_post(text,text,text,smallint,text,boolean,text,text,text),public.vote_feedback_post(uuid),public.watch_feedback_post(uuid),public.flag_feedback_post(uuid,text),public.reply_feedback_post(uuid,text) from public,anon;
grant execute on function public.get_feedback_board(text,text,text,text,boolean,int,int),public.get_feedback_post(uuid),public.submit_feedback_post(text,text,text,smallint,text,boolean,text,text,text),public.vote_feedback_post(uuid),public.watch_feedback_post(uuid),public.flag_feedback_post(uuid,text),public.reply_feedback_post(uuid,text) to authenticated,service_role;
notify pgrst,'reload schema';
